    required this.number,
    required this.nameArabic,
    required this.nameEnglish,
    required this.ayahCount,
    required this.isMeccan,
    required this.startPage,
  });

  String get revelationTypeArabic => isMeccan ? 'مكية' : 'مدنية';
}

